package com.banksorter;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Dev launcher. Running this main() starts a RuneLite client with the Bank
 * Sorter plugin loaded as an external plugin. Use `gradlew run` (which invokes
 * this class) or run it from your IDE.
 */
public class BankSorterPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(BankSorterPlugin.class);
		RuneLite.main(args);
	}
}

package com.banksorter;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.Border;
import javax.swing.border.EmptyBorder;
import javax.swing.border.LineBorder;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.PluginPanel;

class BankSorterPanel extends PluginPanel
{
	private static final Border ON = new LineBorder(new Color(0x3f, 0xd0, 0x3f), 2);
	private static final Border OFF = new EmptyBorder(2, 2, 2, 2);

	private final ConfigManager configManager;
	private final SpriteManager spriteManager;

	private final JCheckBox enabledCheck;
	private final JCheckBox categoryCheck;
	private final JCheckBox hideNoBonusCheck;
	private final JCheckBox statValuesCheck;
	private final JComboBox<SortMode> sortCombo;

	private final Map<EquipSlot, JButton> slotButtons = new EnumMap<>(EquipSlot.class);
	private final Map<StatKey, JButton> statButtons = new EnumMap<>(StatKey.class);
	private final Set<StatKey> selectedStats = new LinkedHashSet<>();
	private EquipSlot selectedSlot;

	private boolean updating;

	BankSorterPanel(ConfigManager configManager, BankSorterConfig config, SpriteManager spriteManager)
	{
		this.configManager = configManager;
		this.spriteManager = spriteManager;

		selectedStats.addAll(StatKey.parse(config.stats()));
		selectedSlot = parseSlot(config.slot());

		setLayout(new BorderLayout());
		final JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBorder(new EmptyBorder(8, 10, 10, 10));

		final JLabel title = new JLabel("Bank Sorter");
		title.setFont(title.getFont().deriveFont(Font.BOLD, 16f));
		title.setAlignmentX(Component.LEFT_ALIGNMENT);
		content.add(title);
		content.add(Box.createVerticalStrut(10));

		enabledCheck = addCheck(content, "Enable sorting", config.enabled(), "enabled");
		content.add(Box.createVerticalStrut(4));
		categoryCheck = addCheck(content, "Group by category", config.groupByCategory(), "groupByCategory");
		content.add(Box.createVerticalStrut(4));
		hideNoBonusCheck = addCheck(content, "Hide items with no bonus", config.hideNoBonus(), "hideNoBonus");
		content.add(Box.createVerticalStrut(4));
		statValuesCheck = addCheck(content, "Show values on items", config.showStatValues(), "showStatValues");
		content.add(Box.createVerticalStrut(12));

		addSectionLabel(content, "Filter by slot");
		content.add(buildSlotGrid());
		content.add(Box.createVerticalStrut(12));

		addSectionLabel(content, "Sort by stat (combine)");
		content.add(buildStatGrid());
		content.add(Box.createVerticalStrut(12));

		addSectionLabel(content, "When no stat is picked");
		sortCombo = new JComboBox<>(SortMode.values());
		sortCombo.setSelectedItem(config.sortMode());
		sortCombo.setAlignmentX(Component.LEFT_ALIGNMENT);
		sortCombo.setMaximumSize(new Dimension(Integer.MAX_VALUE, sortCombo.getPreferredSize().height));
		sortCombo.addActionListener(e ->
		{
			final SortMode mode = (SortMode) sortCombo.getSelectedItem();
			if (!updating && mode != null)
			{
				configManager.setConfiguration(BankSorterConfig.GROUP, "sortMode", mode);
			}
		});
		content.add(sortCombo);

		add(content, BorderLayout.NORTH);
	}

	private JCheckBox addCheck(JPanel parent, String text, boolean selected, String key)
	{
		final JCheckBox box = new JCheckBox(text, selected);
		box.setAlignmentX(Component.LEFT_ALIGNMENT);
		box.addActionListener(e ->
		{
			if (!updating)
			{
				configManager.setConfiguration(BankSorterConfig.GROUP, key, box.isSelected());
			}
		});
		parent.add(box);
		return box;
	}

	private void addSectionLabel(JPanel parent, String text)
	{
		final JLabel label = new JLabel(text);
		label.setFont(label.getFont().deriveFont(Font.BOLD, 13f));
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		parent.add(label);
		parent.add(Box.createVerticalStrut(4));
	}

	private JPanel buildSlotGrid()
	{
		final JPanel grid = new JPanel(new GridBagLayout());
		grid.setAlignmentX(Component.LEFT_ALIGNMENT);
		final GridBagConstraints c = new GridBagConstraints();
		c.insets = new Insets(1, 1, 1, 1);
		for (EquipSlot slot : EquipSlot.values())
		{
			final JButton button = iconButton(slot.getSpriteId(), slot.getLabel(), () -> toggleSlot(slot));
			button.setBorder(slot == selectedSlot ? ON : OFF);
			slotButtons.put(slot, button);
			c.gridx = slot.getCol();
			c.gridy = slot.getRow();
			grid.add(button, c);
		}
		grid.setMaximumSize(grid.getPreferredSize());
		return grid;
	}

	private JPanel buildStatGrid()
	{
		final JPanel wrap = new JPanel();
		wrap.setLayout(new BoxLayout(wrap, BoxLayout.Y_AXIS));
		wrap.setAlignmentX(Component.LEFT_ALIGNMENT);

		for (StatKey.Group group : StatKey.Group.values())
		{
			final JPanel row = new JPanel();
			row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
			row.setAlignmentX(Component.LEFT_ALIGNMENT);
			for (StatKey key : StatKey.values())
			{
				if (key.getGroup() != group)
				{
					continue;
				}
				final JButton button = iconButton(key.getSpriteId(), key.getLabel(), () -> toggleStat(key));
				button.setBackground(groupColor(group));
				button.setOpaque(true);
				button.setContentAreaFilled(true);
				button.setBorder(selectedStats.contains(key) ? ON : OFF);
				statButtons.put(key, button);
				row.add(button);
				row.add(Box.createHorizontalStrut(2));
			}
			row.add(Box.createHorizontalGlue());
			row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
			wrap.add(row);
			wrap.add(Box.createVerticalStrut(2));
		}
		return wrap;
	}

	private static Color groupColor(StatKey.Group group)
	{
		switch (group)
		{
			case ATTACK:
				return new Color(0x6e, 0x2b, 0x2b);
			case DEFENCE:
				return new Color(0x2b, 0x3f, 0x6e);
			default:
				return new Color(0x4a, 0x45, 0x2b);
		}
	}

	private JButton iconButton(int spriteId, String tooltip, Runnable onClick)
	{
		final JButton button = new JButton();
		button.setPreferredSize(new Dimension(32, 32));
		button.setMinimumSize(new Dimension(32, 32));
		button.setToolTipText(tooltip);
		button.setFocusable(false);
		spriteManager.addSpriteTo(button, spriteId, 0);
		button.addActionListener(e -> onClick.run());
		return button;
	}

	private void toggleSlot(EquipSlot slot)
	{
		selectedSlot = (selectedSlot == slot) ? null : slot;
		for (Map.Entry<EquipSlot, JButton> e : slotButtons.entrySet())
		{
			e.getValue().setBorder(e.getKey() == selectedSlot ? ON : OFF);
		}
		configManager.setConfiguration(BankSorterConfig.GROUP, "slot",
			selectedSlot == null ? "" : selectedSlot.name());
	}

	private void toggleStat(StatKey key)
	{
		if (!selectedStats.remove(key))
		{
			selectedStats.add(key);
		}
		statButtons.get(key).setBorder(selectedStats.contains(key) ? ON : OFF);
		configManager.setConfiguration(BankSorterConfig.GROUP, "stats",
			StatKey.toCsv(new ArrayList<>(selectedStats)));
	}

	private static EquipSlot parseSlot(String s)
	{
		if (s == null || s.isEmpty())
		{
			return null;
		}
		try
		{
			return EquipSlot.valueOf(s);
		}
		catch (IllegalArgumentException ex)
		{
			return null;
		}
	}

	void refresh(BankSorterConfig config)
	{
		updating = true;
		try
		{
			enabledCheck.setSelected(config.enabled());
			categoryCheck.setSelected(config.groupByCategory());
			hideNoBonusCheck.setSelected(config.hideNoBonus());
			statValuesCheck.setSelected(config.showStatValues());
			sortCombo.setSelectedItem(config.sortMode());

			selectedStats.clear();
			selectedStats.addAll(StatKey.parse(config.stats()));
			for (Map.Entry<StatKey, JButton> e : statButtons.entrySet())
			{
				e.getValue().setBorder(selectedStats.contains(e.getKey()) ? ON : OFF);
			}

			selectedSlot = parseSlot(config.slot());
			for (Map.Entry<EquipSlot, JButton> e : slotButtons.entrySet())
			{
				e.getValue().setBorder(e.getKey() == selectedSlot ? ON : OFF);
			}
		}
		finally
		{
			updating = false;
		}
	}
}

package com.banksorter;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(BankSorterConfig.GROUP)
public interface BankSorterConfig extends Config
{
	String GROUP = "banksorter";

	@ConfigItem(
		keyName = "enabled",
		name = "Enable sorting",
		description = "Reorder how the bank is displayed. Turn off to fall back to the game's normal order (reopen the bank to see it restored).",
		position = 0
	)
	default boolean enabled()
	{
		return true;
	}

	@ConfigItem(
		keyName = "groupByCategory",
		name = "Group by category",
		description = "Group items into auto-detected category sections with headers. Combines with 'Sort by', which orders items within each category.",
		position = 1
	)
	default boolean groupByCategory()
	{
		return true;
	}

	@ConfigItem(
		keyName = "sortMode",
		name = "Sort by",
		description = "How items are ordered (within each category when grouping is on): alphabetically, or ranked by an equipment stat.",
		position = 2
	)
	default SortMode sortMode()
	{
		return SortMode.NAME;
	}

	@ConfigItem(
		keyName = "hideNoBonus",
		name = "Hide items with no bonus",
		description = "When a stat sort is active, hide items that give no bonus for it (e.g. with 'Best prayer bonus', hide everything with no prayer bonus). No effect for Name sort.",
		position = 3
	)
	default boolean hideNoBonus()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showStatValues",
		name = "Show values on items",
		description = "Draw each item's value on its icon: the selected stat total when stat icons are picked, the GE price during 'Best value', or weight / attack speed.",
		position = 4
	)
	default boolean showStatValues()
	{
		return true;
	}


	@ConfigItem(keyName = "stats", name = "", description = "", hidden = true)
	default String stats()
	{
		return "";
	}


	@ConfigItem(keyName = "slot", name = "", description = "", hidden = true)
	default String slot()
	{
		return "";
	}


	@ConfigItem(keyName = "categoryOverrides", name = "", description = "", hidden = true)
	default String categoryOverrides()
	{
		return "";
	}
}

package com.banksorter;

import java.util.function.ToDoubleFunction;
import lombok.Getter;
import net.runelite.client.game.ItemStats;

//Default ordering
@Getter
public enum SortMode
{
	NAME("Name (A - Z)", Kind.NAME, false, null),
	VALUE("Best value (GE)", Kind.VALUE, true, null),
	QUANTITY("Largest quantity", Kind.QUANTITY, true, null),
	WEIGHT("Lightest weight", Kind.STAT, false, s -> s.getEquipment() == null ? Double.NaN : s.getWeight()),
	SPEED("Fastest attack speed", Kind.STAT, false, s -> s.getEquipment() == null ? Double.NaN : s.getEquipment().getAspeed());

	enum Kind
	{
		NAME, STAT, VALUE, QUANTITY
	}

	private final String label;
	private final Kind kind;
	private final boolean higherIsBetter;
	private final ToDoubleFunction<ItemStats> statExtractor;

	SortMode(String label, Kind kind, boolean higherIsBetter, ToDoubleFunction<ItemStats> statExtractor)
	{
		this.label = label;
		this.kind = kind;
		this.higherIsBetter = higherIsBetter;
		this.statExtractor = statExtractor;
	}

	boolean isStatSort()
	{
		return kind == Kind.STAT;
	}

	boolean isValueSort()
	{
		return kind == Kind.VALUE;
	}

	boolean isQuantitySort()
	{
		return kind == Kind.QUANTITY;
	}

	//value format
	String format(double v)
	{
		if (this == WEIGHT)
		{
			return String.format("%.1f", v);
		}
		return Integer.toString((int) v);
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.banksorter;

import java.util.ArrayList;
import java.util.List;
import java.util.function.ToIntFunction;
import lombok.Getter;
import net.runelite.api.SpriteID;
import net.runelite.client.game.ItemEquipmentStats;


@Getter
enum StatKey
{
	ATK_STAB(Group.ATTACK, "Attack: Stab", SpriteID.COMBAT_STYLE_SWORD_STAB, ItemEquipmentStats::getAstab),
	ATK_SLASH(Group.ATTACK, "Attack: Slash", SpriteID.COMBAT_STYLE_SWORD_SLASH, ItemEquipmentStats::getAslash),
	ATK_CRUSH(Group.ATTACK, "Attack: Crush", SpriteID.COMBAT_STYLE_MACE_POUND, ItemEquipmentStats::getAcrush),
	ATK_MAGIC(Group.ATTACK, "Attack: Magic", SpriteID.SKILL_MAGIC, ItemEquipmentStats::getAmagic),
	ATK_RANGE(Group.ATTACK, "Attack: Ranged", SpriteID.SKILL_RANGED, ItemEquipmentStats::getArange),

	DEF_STAB(Group.DEFENCE, "Defence: Stab", SpriteID.COMBAT_STYLE_SWORD_STAB, ItemEquipmentStats::getDstab),
	DEF_SLASH(Group.DEFENCE, "Defence: Slash", SpriteID.COMBAT_STYLE_SWORD_SLASH, ItemEquipmentStats::getDslash),
	DEF_CRUSH(Group.DEFENCE, "Defence: Crush", SpriteID.COMBAT_STYLE_MACE_POUND, ItemEquipmentStats::getDcrush),
	DEF_MAGIC(Group.DEFENCE, "Defence: Magic", SpriteID.SKILL_MAGIC, ItemEquipmentStats::getDmagic),
	DEF_RANGE(Group.DEFENCE, "Defence: Ranged", SpriteID.SKILL_RANGED, ItemEquipmentStats::getDrange),

	STRENGTH(Group.OTHER, "Melee strength", SpriteID.SKILL_STRENGTH, ItemEquipmentStats::getStr),
	RANGE_STR(Group.OTHER, "Ranged strength", SpriteID.SKILL_RANGED, ItemEquipmentStats::getRstr),
	MAGIC_DMG(Group.OTHER, "Magic damage", SpriteID.SKILL_MAGIC_RED, e -> (int) e.getMdmg()),
	PRAYER(Group.OTHER, "Prayer bonus", SpriteID.SKILL_PRAYER, ItemEquipmentStats::getPrayer);

	enum Group
	{
		ATTACK, DEFENCE, OTHER
	}

	private final Group group;
	private final String label;
	private final int spriteId;
	private final ToIntFunction<ItemEquipmentStats> extractor;

	StatKey(Group group, String label, int spriteId, ToIntFunction<ItemEquipmentStats> extractor)
	{
		this.group = group;
		this.label = label;
		this.spriteId = spriteId;
		this.extractor = extractor;
	}

	int value(ItemEquipmentStats e)
	{
		return extractor.applyAsInt(e);
	}

	static List<StatKey> parse(String csv)
	{
		final List<StatKey> out = new ArrayList<>();
		if (csv == null || csv.isEmpty())
		{
			return out;
		}
		for (String part : csv.split(","))
		{
			final String trimmed = part.trim();
			if (trimmed.isEmpty())
			{
				continue;
			}
			try
			{
				out.add(StatKey.valueOf(trimmed));
			}
			catch (IllegalArgumentException ignored)
			{
				// if unknown skip
			}
		}
		return out;
	}

	static String toCsv(List<StatKey> keys)
	{
		final StringBuilder sb = new StringBuilder();
		for (StatKey k : keys)
		{
			if (sb.length() > 0)
			{
				sb.append(',');
			}
			sb.append(k.name());
		}
		return sb.toString();
	}
}

package com.banksorter;

import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;

//Automatic category assignement

@Singleton
class ItemCategorizer
{
	private static final int WEAPON_SLOT = EquipmentInventorySlot.WEAPON.getSlotIdx();
	private static final int AMMO_SLOT = EquipmentInventorySlot.AMMO.getSlotIdx();
	private static final int AMULET_SLOT = EquipmentInventorySlot.AMULET.getSlotIdx();
	private static final int RING_SLOT = EquipmentInventorySlot.RING.getSlotIdx();

	private final ItemManager itemManager;
	private final BankSorterConfig config;

	private String cachedOverrideCsv;
	private Map<Integer, ItemCategory> overrides = new HashMap<>();

	@Inject
	ItemCategorizer(ItemManager itemManager, BankSorterConfig config)
	{
		this.itemManager = itemManager;
		this.config = config;
	}

	ItemCategory categorize(int itemId)
	{
		final int id = itemManager.canonicalize(itemId);

		final ItemCategory override = overrides().get(id);
		if (override != null)
		{
			return override;
		}

		final ItemComposition comp = itemManager.getItemComposition(id);
		final String name = comp.getName() == null ? "" : comp.getName().toLowerCase();
		final String[] actions = comp.getInventoryActions();
		final ItemStats stats = itemManager.getItemStats(id);
		final boolean equipable = stats != null && stats.isEquipable();

		if (isTeleport(name, actions, equipable))
		{
			return ItemCategory.TELEPORTS;
		}

		final ItemCategory tool = skillTool(name);
		if (tool != null)
		{
			return tool;
		}

		if (isThrownWeapon(name))
		{
			return ItemCategory.RANGED_WEAPON;
		}

		if (equipable && stats.getEquipment() != null)
		{
			final ItemCategory eq = categorizeEquipment(stats.getEquipment(), name);
			if (eq != null)
			{
				return eq;
			}
		}

		return categorizeByName(comp, name);
	}

	//Teleports

	private boolean isTeleport(String name, String[] actions, boolean equipable)
	{
		if (name.contains("teleport") || name.contains("teletab"))
		{
			return true;
		}
		if (hasAction(actions, "Break")
			|| (equipable && hasAction(actions, "Rub"))
			|| hasAction(actions, "Teleport")
			|| hasAction(actions, "Invoke"))
		{
			return true;
		}
		return containsAny(name,
			"glory", "games necklace", "ring of dueling", "ring of wealth",
			"skills necklace", "combat bracelet", "digsite pendant", "necklace of passage",
			"burning amulet", "slayer ring", "ring of returning", "ring of the elements",
			"amulet of eternal glory", "pharaoh's sceptre", "royal seed pod",
			"xeric's talisman", "drakan's medallion", "giantsoul amulet", "medallion",
			"quetzal whistle", "ring of shadows", "ectophial", "enchanted lyre", "camulet",
			"kharedst's memoirs");
	}

	//Skilling tools

	private ItemCategory skillTool(String name)
	{
		if (name.contains("pickaxe"))
		{
			return ItemCategory.MINING;
		}
		if (isWoodcuttingAxe(name))
		{
			return ItemCategory.WOODCUTTING;
		}
		if (containsAny(name, "harpoon", "fishing rod", "fishing net", "lobster pot", "karambwan vessel"))
		{
			return ItemCategory.FISHING;
		}
		if (name.contains("tinderbox"))
		{
			return ItemCategory.FIREMAKING;
		}
		if (containsAny(name, "watering can", "seed dibber", "gardening trowel", "secateurs")
			|| name.equals("rake") || name.equals("spade"))
		{
			return ItemCategory.FARMING;
		}
		if (name.contains("pestle and mortar"))
		{
			return ItemCategory.HERBLORE;
		}
		if (name.contains("glassblowing") || name.contains("imcando hammer")
			|| name.equals("needle") || name.equals("chisel") || name.equals("shears"))
		{
			return ItemCategory.CRAFTING;
		}
		if (name.equals("hammer"))
		{
			return ItemCategory.SMITHING;
		}
		if (containsAny(name, "butterfly net", "bird snare", "box trap", "noose wand",
			"magic box", "teasing stick", "impling jar"))
		{
			return ItemCategory.HUNTER;
		}
		if (name.equals("saw") || name.contains("crystal saw"))
		{
			return ItemCategory.CONSTRUCTION;
		}
		return null;
	}

	private boolean isWoodcuttingAxe(String name)
	{
		if (!name.endsWith(" axe"))
		{
			return false;
		}
		switch (name.substring(0, name.length() - 4))
		{
			case "bronze":
			case "iron":
			case "steel":
			case "black":
			case "mithril":
			case "adamant":
			case "rune":
			case "gilded":
			case "dragon":
			case "infernal":
			case "crystal":
			case "3rd age":
			case "blessed":
				return true;
			default:
				return false;
		}
	}

	//Thrown weapons

	private boolean isThrownWeapon(String name)
	{
		if (name.contains("dart"))
		{
			return !name.contains("dart tip");
		}
		return name.contains(" knife") || name.contains("throwing axe") || name.contains("chinchompa");
	}

	//Equipments

	private static boolean isMagicWeaponName(String name)
	{
		return name.contains("staff") || name.contains("wand") || name.contains("trident");
	}

	private ItemCategory categorizeEquipment(ItemEquipmentStats e, String name)
	{
		final int slot = e.getSlot();

		if (slot == AMMO_SLOT)
		{
			return ItemCategory.AMMUNITION;
		}
		if (slot == AMULET_SLOT)
		{
			return ItemCategory.NECKLACE;
		}
		if (slot == RING_SLOT)
		{
			return ItemCategory.RING;
		}

		final int melee = max3(e.getAstab(), e.getAslash(), e.getAcrush());
		final int mage = e.getAmagic();
		final int ranged = e.getArange();

		if (slot == WEAPON_SLOT)
		{
			if (isMagicWeaponName(name) || (mage > melee && mage >= ranged))
			{
				return ItemCategory.MAGIC_WEAPON;
			}
			if (ranged > melee && ranged >= mage)
			{
				return ItemCategory.RANGED_WEAPON;
			}
			return ItemCategory.MELEE_WEAPON;
		}

		//Equippable but completely statless items (Collection log, cosmetics)

		if (isStatless(e))
		{
			return null;
		}

		if (mage > 0 && mage >= ranged)
		{
			return ItemCategory.MAGIC_ARMOUR;
		}
		if (ranged > 0 && ranged >= mage)
		{
			return ItemCategory.RANGED_ARMOUR;
		}
		return ItemCategory.MELEE_ARMOUR;
	}

	private static boolean isStatless(ItemEquipmentStats e)
	{
		return e.getAstab() == 0 && e.getAslash() == 0 && e.getAcrush() == 0
			&& e.getAmagic() == 0 && e.getArange() == 0
			&& e.getDstab() == 0 && e.getDslash() == 0 && e.getDcrush() == 0
			&& e.getDmagic() == 0 && e.getDrange() == 0
			&& e.getStr() == 0 && e.getRstr() == 0 && e.getPrayer() == 0
			&& e.getMdmg() == 0f;
	}

	//Name categorizing

	private ItemCategory categorizeByName(ItemComposition comp, String name)
	{
		final String[] actions = comp.getInventoryActions();

		if (hasAction(actions, "Drink")
			|| name.matches(".*\\(\\d\\)$")
			|| containsAny(name, "potion", "brew", "antipoison", "antidote", "antifire",
				"stamina", "restore", "serum"))
		{
			return ItemCategory.POTIONS;
		}

		if (hasAction(actions, "Eat"))
		{
			return ItemCategory.FOOD;
		}

		if (name.endsWith("rune") || name.endsWith("runes"))
		{
			return ItemCategory.RUNES;
		}

		//Fletching materials
		if (containsAny(name, "headless arrow", "arrow shaft", "bow string", "unstrung",
			"dart tip", "javelin shaft", "feather"))
		{
			return ItemCategory.FLETCHING;
		}

		if (containsAny(name, "arrow", "bolt", "javelin", "cannonball", "brutal", "tipped"))
		{
			return ItemCategory.AMMUNITION;
		}

		final ItemCategory skill = skillResource(name);
		if (skill != null)
		{
			return skill;
		}

		if (containsAny(name, "coins", "token", "platinum", "points", "blood money"))
		{
			return ItemCategory.CURRENCY;
		}

		return ItemCategory.MISC;
	}

	private ItemCategory skillResource(String name)
	{
		if (containsAny(name, "grimy", "clean ", "herb", "vial", "unfinished potion",
			"snape grass", "limpwurt", "eye of newt", "unicorn horn"))
		{
			return ItemCategory.HERBLORE;
		}
		if (containsAny(name, "seed", "sapling", "seedling", "compost", "plant pot", "saltpetre"))
		{
			return ItemCategory.FARMING;
		}
		if (containsAny(name, " ore", "coal", "clay", "geode"))
		{
			return ItemCategory.MINING;
		}
		if (name.contains(" bar"))
		{
			return ItemCategory.SMITHING;
		}
		if (name.contains("logs"))
		{
			return ItemCategory.WOODCUTTING;
		}
		if (name.contains("ashes"))
		{
			return ItemCategory.FIREMAKING;
		}
		if (containsAny(name, "essence", "talisman", "tiara"))
		{
			return ItemCategory.RUNECRAFT;
		}
		if (containsAny(name, "raw ", "pot of flour", "bucket of milk", "cake tin", "pie dish"))
		{
			return ItemCategory.COOKING;
		}
		if (containsAny(name, "plank", "bolt of cloth", "steel nails", "marble block", "limestone brick"))
		{
			return ItemCategory.CONSTRUCTION;
		}
		if (containsAny(name, "uncut", "sapphire", "emerald", "ruby", "diamond", "dragonstone",
			"onyx", "zenyte", "opal", "jade", "topaz", "leather", "dragonhide", "snakeskin",
			"molten glass", "ball of wool", "thread", "mould", "gold "))
		{
			return ItemCategory.CRAFTING;
		}
		return null;
	}

	//manual overrides

	private Map<Integer, ItemCategory> overrides()
	{
		final String csv = config.categoryOverrides();
		if (!Objects.equals(csv, cachedOverrideCsv))
		{
			cachedOverrideCsv = csv;
			overrides = parseOverrides(csv);
		}
		return overrides;
	}

	static Map<Integer, ItemCategory> parseOverrides(String csv)
	{
		final Map<Integer, ItemCategory> map = new HashMap<>();
		if (csv == null || csv.isEmpty())
		{
			return map;
		}
		for (String part : csv.split(","))
		{
			final int eq = part.indexOf('=');
			if (eq <= 0)
			{
				continue;
			}
			try
			{
				map.put(Integer.parseInt(part.substring(0, eq).trim()),
					ItemCategory.valueOf(part.substring(eq + 1).trim()));
			}
			catch (IllegalArgumentException ignored)
			{
				//skip
			}
		}
		return map;
	}

	static String serializeOverrides(Map<Integer, ItemCategory> map)
	{
		final StringBuilder sb = new StringBuilder();
		for (Map.Entry<Integer, ItemCategory> e : map.entrySet())
		{
			if (sb.length() > 0)
			{
				sb.append(',');
			}
			sb.append(e.getKey()).append('=').append(e.getValue().name());
		}
		return sb.toString();
	}

	//helpers

	private static int max3(int a, int b, int c)
	{
		return Math.max(a, Math.max(b, c));
	}

	private static boolean hasAction(String[] actions, String target)
	{
		if (actions == null)
		{
			return false;
		}
		for (String a : actions)
		{
			if (target.equalsIgnoreCase(a))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean containsAny(String haystack, String... needles)
	{
		for (String n : needles)
		{
			if (haystack.contains(n))
			{
				return true;
			}
		}
		return false;
	}
}

