import net.runelite.client.ui.overlay.WidgetItemOverlay;

//Draw the values for each bank assets

class BankStatOverlay extends WidgetItemOverlay
{
	private final BankSorterConfig config;
	private final ItemManager itemManager;

	private String cachedStatsCsv;
	private List<StatKey> cachedStats = Collections.emptyList();

	BankStatOverlay(BankSorterConfig config, ItemManager itemManager)
	{
		this.config = config;
		this.itemManager = itemManager;
		showOnBank();
	}

	private List<StatKey> selectedStats()
	{
		final String csv = config.stats();
		if (!Objects.equals(csv, cachedStatsCsv))
		{
			cachedStatsCsv = csv;
			cachedStats = StatKey.parse(csv);
		}
		return cachedStats;
	}

	private static final int LINE_HEIGHT = 9;

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!config.showStatValues())
		{
			return;
		}

		final int id = itemManager.canonicalize(itemId);
		final String[] lines = valueLines(id);
		if (lines == null || lines.length == 0)
		{
			return;
		}

		final Rectangle bounds = widgetItem.getCanvasBounds();
		graphics.setFont(FontManager.getRunescapeSmallFont());
		final FontMetrics fm = graphics.getFontMetrics();


		for (int i = 0; i < lines.length; i++)
		{
			final String text = lines[i];
			final int x = bounds.x + (bounds.width - fm.stringWidth(text)) / 2;
			final int y = bounds.y + bounds.height - 1 - (lines.length - 1 - i) * LINE_HEIGHT;

			graphics.setColor(Color.BLACK);
			graphics.drawString(text, x + 1, y + 1);
			graphics.setColor(Color.YELLOW);
			graphics.drawString(text, x, y);
		}
	}

	private String[] valueLines(int id)
	{
		final List<StatKey> stats = selectedStats();
		if (!stats.isEmpty())
		{
			final ItemStats s = itemManager.getItemStats(id);
			final ItemEquipmentStats e = s == null ? null : s.getEquipment();
			if (e == null)
			{
				return null;
			}
			final String[] lines = new String[stats.size()];
			for (int i = 0; i < stats.size(); i++)
			{
				final int v = stats.get(i).value(e);
				if (v <= 0)
				{
					return null;
				}
				lines[i] = "+" + v;
			}
			return lines;
		}

		final SortMode mode = config.sortMode();
		if (mode.isValueSort())
		{
			final int price = itemManager.getItemPrice(id);
			return price <= 0 ? null : new String[]{abbreviate(price)};
		}
		if (mode.isStatSort())
		{
			final ItemStats s = itemManager.getItemStats(id);
			if (s == null)
			{
				return null;
			}
			final double v = mode.getStatExtractor().applyAsDouble(s);
			return Double.isNaN(v) ? null : new String[]{mode.format(v)};
		}
		return null;
	}

	//Compact GP values
	private static String abbreviate(int gp)
	{
		if (gp >= 1_000_000_000)
		{
			return String.format("%.1fB", gp / 1_000_000_000.0);
		}
		if (gp >= 1_000_000)
		{
			return String.format("%.1fM", gp / 1_000_000.0);
		}
		if (gp >= 1_000)
		{
			return String.format("%.1fK", gp / 1_000.0);
		}
		return Integer.toString(gp);
	}
}

