)
public class BankSorterPlugin extends Plugin
{
	// Bank item grid (mirrors RuneLite core BankTagsPlugin constants).
	private static final int ITEMS_PER_ROW = 8;
	private static final int X_STEP = 48;
	private static final int Y_STEP = 36;
	private static final int START_X = 51;
	private static final int START_Y = 0;
	private static final int ROW_WIDTH = ITEMS_PER_ROW * X_STEP;

	// Vertical space consumed by a category header and by tab separators.
	private static final int HEADER_HEIGHT = 15;
	private static final int TAB_GAP = 12;

	private static final int GROUP_GAP_THRESHOLD = Y_STEP + 8;

	private static final int HEADER_COLOR = 0xffb33e;
	private static final int LINE_COLOR = 0x5a5a5a;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private BankSorterConfig config;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ItemCategorizer categorizer;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private SpriteManager spriteManager;


	private final List<Widget> textPool = new ArrayList<>();
	private final List<Widget> linePool = new ArrayList<>();
	private int textUsed;
	private int lineUsed;

	private final Map<Widget, String> nameCache = new IdentityHashMap<>();
	private final Map<Widget, ItemCategory> catCache = new IdentityHashMap<>();
	private final Map<Widget, Double> keyCache = new IdentityHashMap<>();

	private BankSorterPanel panel;
	private NavigationButton navButton;
	private BankStatOverlay statOverlay;

	@Override
	protected void startUp()
	{
		log.debug("Bank Sorter started");

		statOverlay = new BankStatOverlay(config, itemManager);
		overlayManager.add(statOverlay);

		panel = new BankSorterPanel(configManager, config, spriteManager);
		navButton = NavigationButton.builder()
			.tooltip("Bank Sorter")
			.icon(buildIcon())
			.priority(8)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		clientThread.invokeLater(this::rebuildBank);
	}

	@Override
	protected void shutDown()
	{
		log.debug("Bank Sorter stopped");

		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		panel = null;

		if (statOverlay != null)
		{
			overlayManager.remove(statOverlay);
			statOverlay = null;
		}

		clientThread.invokeLater(() ->
		{
			hideAll(textPool);
			hideAll(linePool);
			textPool.clear();
			linePool.clear();
			nameCache.clear();
			catCache.clear();
			keyCache.clear();
		});
	}

	// Hides every pooled header/line widget
	private void hideManaged()
	{
		hideAll(textPool);
		hideAll(linePool);
	}

	private static void hideAll(List<Widget> widgets)
	{
		for (Widget w : widgets)
		{
			if (w != null)
			{
				w.setHidden(true);
			}
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{

		if (event.getScriptId() == ScriptID.BANKMAIN_BUILD)
		{
			layoutBank();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (BankSorterConfig.GROUP.equals(event.getGroup()))
		{
			final BankSorterPanel p = panel;
			if (p != null)
			{
				SwingUtilities.invokeLater(() -> p.refresh(config));
			}
			// Force a full bank rebuild
			clientThread.invokeLater(this::rebuildBank);
		}
	}

	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		final int itemId = rightClickedBankItem(event.getMenuEntries());
		if (itemId <= 0)
		{
			return;
		}

		final int id = itemManager.canonicalize(itemId);
		final Menu submenu = client.getMenu()
			.createMenuEntry(-1)
			.setOption("Set category")
			.setType(MenuAction.RUNELITE)
			.createSubMenu();

		submenu.createMenuEntry(-1)
			.setOption("Auto-detect")
			.setType(MenuAction.RUNELITE)
			.onClick(e -> clearOverride(id));

		for (ItemCategory category : ItemCategory.values())
		{
			submenu.createMenuEntry(-1)
				.setOption(category.getDisplayName())
				.setType(MenuAction.RUNELITE)
				.onClick(e -> setOverride(id, category));
		}
	}

	private int rightClickedBankItem(MenuEntry[] entries)
	{
		for (MenuEntry entry : entries)
		{
			if (entry.getParam1() != InterfaceID.Bankmain.ITEMS)
			{
				continue;
			}
			final Widget w = entry.getWidget();
			if (w != null && w.getItemId() > 0)
			{
				return w.getItemId();
			}
			if (entry.getItemId() > 0)
			{
				return entry.getItemId();
			}
		}
		return -1;
	}

	private void setOverride(int itemId, ItemCategory category)
	{
		final Map<Integer, ItemCategory> map =
			ItemCategorizer.parseOverrides(config.categoryOverrides());
		map.put(itemId, category);
		configManager.setConfiguration(BankSorterConfig.GROUP, "categoryOverrides",
			ItemCategorizer.serializeOverrides(map));
	}

	private void clearOverride(int itemId)
	{
		final Map<Integer, ItemCategory> map =
			ItemCategorizer.parseOverrides(config.categoryOverrides());
		if (map.remove(itemId) != null)
		{
			configManager.setConfiguration(BankSorterConfig.GROUP, "categoryOverrides",
				ItemCategorizer.serializeOverrides(map));
		}
	}

	private void rebuildBank()
	{
		final Widget universe = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		if (universe == null)
		{
			return;
		}
		final Object[] onLoad = universe.getOnLoadListener();
		if (onLoad == null)
		{
			return;
		}
		client.createScriptEventBuilder(onLoad)
			.setSource(universe)
			.build()
			.run();
	}

	private static BufferedImage buildIcon()
	{
		final BufferedImage img = new BufferedImage(24, 24, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		g.setColor(new Color(0xff, 0xb3, 0x3e));
		g.fillRect(3, 4, 18, 3);
		g.fillRect(3, 11, 13, 3);
		g.fillRect(3, 18, 8, 3);
		g.dispose();
		return img;
	}


	private void layoutBank()
	{
		final Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (container == null || container.isHidden())
		{
			return;
		}

		// When disabled or the bank has no items
		if (!config.enabled())
		{
			hideManaged();
			return;
		}

		final Widget[] children = container.getDynamicChildren();
		if (children == null || children.length == 0)
		{
			hideManaged();
			return;
		}

		try
		{

			beginManaged(container);

			final List<Widget> items = new ArrayList<>();
			for (Widget w : children)
			{
				if (w == null || w.isSelfHidden())
				{
					continue;
				}
				if (w.getItemId() > 0)
				{
					items.add(w);
				}
				else
				{
					w.setHidden(true);
				}
			}

			if (items.isEmpty())
			{
				endManaged();
				return;
			}

			precompute(items);

			final int total = items.size();
			int looseCount = 0;
			if (client.getVarbitValue(VarbitID.BANK_CURRENTTAB) == 0)
			{
				int assigned = 0;
				for (int i = 0; i < 9; i++)
				{
					assigned += client.getVarbitValue(VarbitID.BANK_TAB_1 + i);
				}
				looseCount = total - assigned;
				if (looseCount < 0 || looseCount > total)
				{
					looseCount = 0;
				}
			}

			List<Widget> looseItems = null;
			List<Widget> assignedItems = items;
			if (looseCount > 0)
			{
				looseItems = new ArrayList<>(items.subList(total - looseCount, total));
				assignedItems = new ArrayList<>(items.subList(0, total - looseCount));
			}

			final List<List<Widget>> tabGroups =
				assignedItems.isEmpty() ? new ArrayList<>() : splitIntoTabGroups(assignedItems);

			int y = START_Y;
			boolean firstGroup = true;

			final List<Widget> loose = applyFilters(looseItems);
			if (loose != null && !loose.isEmpty())
			{
				y = layoutRaw(container, loose, y);
				firstGroup = false;
			}

			for (List<Widget> group : tabGroups)
			{
				final List<Widget> filtered = applyFilters(group);
				if (filtered.isEmpty())
				{
					continue;
				}
				if (!firstGroup)
				{
					y += TAB_GAP / 2;
					drawLine(container, y);
					y += TAB_GAP / 2;
				}
				firstGroup = false;
				y = layoutGroup(container, filtered, y);
			}

			endManaged();

			final int contentHeight = y + 3;
			container.setScrollHeight(contentHeight);
			container.revalidateScroll();
			container.revalidate();

			final Widget scrollbar = client.getWidget(InterfaceID.Bankmain.SCROLLBAR);
			if (scrollbar != null)
			{
				final int scrollbarId = scrollbar.getId();
				final int containerId = container.getId();
				final int maxScroll = Math.max(0, contentHeight - container.getHeight());
				final int scrollY = Math.min(container.getScrollY(), maxScroll);
				clientThread.invokeLater(() ->
					client.runScript(ScriptID.UPDATE_SCROLLBAR, scrollbarId, containerId, scrollY));
			}
		}
		catch (Exception ex)
		{
			log.warn("Bank Sorter layout failed", ex);
		}
	}

	private List<List<Widget>> splitIntoTabGroups(List<Widget> items)
	{
		final List<List<Widget>> groups = new ArrayList<>();
		List<Widget> current = new ArrayList<>();
		int lastRowY = items.get(0).getOriginalY();

		for (Widget w : items)
		{
			final int wy = w.getOriginalY();
			if (!current.isEmpty() && wy - lastRowY > GROUP_GAP_THRESHOLD)
			{
				groups.add(current);
				current = new ArrayList<>();
			}
			if (wy != lastRowY)
			{
				lastRowY = wy;
			}
			current.add(w);
		}

		if (!current.isEmpty())
		{
			groups.add(current);
		}
		return groups;
	}

	private int layoutGroup(Widget container, List<Widget> group, int y)
	{
		final Comparator<Widget> within = activeComparator();

		if (config.groupByCategory())
		{
			return layoutByCategory(container, group, y, within);
		}

		group.sort(within);
		return layoutRaw(container, group, y);
	}

	private int layoutByCategory(Widget container, List<Widget> group, int y, Comparator<Widget> within)
	{
		group.sort(Comparator.<Widget>comparingInt(w -> cachedCategory(w).ordinal())
			.thenComparing(within));
		int col = 0;
		ItemCategory currentCat = null;
		for (Widget w : group)
		{
			final ItemCategory cat = cachedCategory(w);
			if (cat != currentCat)
			{
				if (col != 0)
				{
					y += Y_STEP;
					col = 0;
				}
				drawHeader(container, y, cat.getDisplayName());
				y += HEADER_HEIGHT;
				currentCat = cat;
			}
			placeItem(w, START_X + col * X_STEP, y);
			if (++col == ITEMS_PER_ROW)
			{
				col = 0;
				y += Y_STEP;
			}
		}
		if (col != 0)
		{
			y += Y_STEP;
		}
		return y;
	}

	private int layoutRaw(Widget container, List<Widget> group, int y)
	{
		int col = 0;
		for (Widget w : group)
		{
			placeItem(w, START_X + col * X_STEP, y);
			if (++col == ITEMS_PER_ROW)
			{
				col = 0;
				y += Y_STEP;
			}
		}
		if (col != 0)
		{
			y += Y_STEP;
		}
		return y;
	}

	private void placeItem(Widget w, int x, int y)
	{
		w.setOriginalX(x);
		w.setOriginalY(y);
		w.setHidden(false);
		w.revalidate();
	}

	private Comparator<Widget> activeComparator()
	{
		final SortMode base = config.sortMode();
		final boolean combo = comboActive();
		if (!combo && base == SortMode.NAME)
		{
			return Comparator.comparing(this::cachedName, String.CASE_INSENSITIVE_ORDER);
		}

		final boolean higher = combo || base.isHigherIsBetter();
		return (a, b) ->
		{
			final double va = cachedKey(a);
			final double vb = cachedKey(b);
			final boolean na = Double.isNaN(va);
			final boolean nb = Double.isNaN(vb);
			if (na || nb)
			{
				if (na && nb)
				{
					return cachedName(a).compareToIgnoreCase(cachedName(b));
				}
				return na ? 1 : -1;
			}
			final int cmp = higher ? Double.compare(vb, va) : Double.compare(va, vb);
			return cmp != 0 ? cmp : cachedName(a).compareToIgnoreCase(cachedName(b));
		};
	}

	private boolean comboActive()
	{
		return !StatKey.parse(config.stats()).isEmpty();
	}

	private void precompute(List<Widget> items)
	{
		nameCache.clear();
		catCache.clear();
		keyCache.clear();

		final boolean groupByCat = config.groupByCategory();
		final List<StatKey> stats = StatKey.parse(config.stats());
		final boolean combo = !stats.isEmpty();
		final SortMode base = config.sortMode();

		for (Widget w : items)
		{
			nameCache.put(w, itemName(w));
			if (groupByCat)
			{
				catCache.put(w, categorizer.categorize(w.getItemId()));
			}
			keyCache.put(w, combo ? comboKey(w, stats) : baseKey(w, base));
		}
	}

	private double baseKey(Widget w, SortMode mode)
	{
		if (mode.isValueSort())
		{
			return itemManager.getItemPrice(itemManager.canonicalize(w.getItemId()));
		}
		if (mode.isQuantitySort())
		{
			return w.getItemQuantity();
		}
		if (mode.isStatSort())
		{
			final ItemStats stats = itemManager.getItemStats(itemManager.canonicalize(w.getItemId()));
			return stats == null ? Double.NaN : mode.getStatExtractor().applyAsDouble(stats);
		}
		return Double.NaN;
	}

	private double comboKey(Widget w, List<StatKey> stats)
	{
		final ItemEquipmentStats e = equipmentOf(w);
		if (e == null)
		{
			return Double.NaN;
		}
		int sum = 0;
		for (StatKey k : stats)
		{
			final int v = k.value(e);
			if (v <= 0)
			{
				return Double.NaN;
			}
			sum += v;
		}
		return sum;
	}

	private ItemEquipmentStats equipmentOf(Widget w)
	{
		final ItemStats stats = itemManager.getItemStats(itemManager.canonicalize(w.getItemId()));
		return stats == null ? null : stats.getEquipment();
	}

	private String cachedName(Widget w)
	{
		return nameCache.computeIfAbsent(w, this::itemName);
	}

	private double cachedKey(Widget w)
	{
		final Double v = keyCache.get(w);
		return v == null ? Double.NaN : v;
	}

	private ItemCategory cachedCategory(Widget w)
	{
		return catCache.computeIfAbsent(w, x -> categorizer.categorize(x.getItemId()));
	}

	private List<Widget> applyFilters(List<Widget> items)
	{
		if (items == null)
		{
			return null;
		}

		final List<StatKey> stats = StatKey.parse(config.stats());
		final boolean comboActive = !stats.isEmpty();
		final int slotIdx = selectedSlotIdx();
		final SortMode base = config.sortMode();
		final boolean hideActive = config.hideNoBonus() && (comboActive || base.isStatSort());

		if (slotIdx < 0 && !hideActive)
		{
			return items;
		}

		final List<Widget> kept = new ArrayList<>();
		for (Widget w : items)
		{
			final ItemEquipmentStats e = equipmentOf(w);

			if (slotIdx >= 0 && (e == null || e.getSlot() != slotIdx))
			{
				w.setHidden(true);
				continue;
			}

			if (hideActive)
			{

				final boolean bonus = comboActive ? !Double.isNaN(cachedKey(w)) : e != null;
				if (!bonus)
				{
					w.setHidden(true);
					continue;
				}
			}

			kept.add(w);
		}
		return kept;
	}

	private int selectedSlotIdx()
	{
		final String s = config.slot();
		if (s == null || s.isEmpty())
		{
			return -1;
		}
		try
		{
			return EquipSlot.valueOf(s).getSlotIdx();
		}
		catch (IllegalArgumentException ex)
		{
			return -1;
		}
	}

	private String itemName(Widget w)
	{
		return itemManager.getItemComposition(itemManager.canonicalize(w.getItemId())).getName();
	}

	private void beginManaged(Widget container)
	{
		if (!poolAttached(container, textPool))
		{
			textPool.clear();
		}
		if (!poolAttached(container, linePool))
		{
			linePool.clear();
		}
		textUsed = 0;
		lineUsed = 0;
	}

	private void endManaged()
	{
		for (int i = textUsed; i < textPool.size(); i++)
		{
			textPool.get(i).setHidden(true);
		}
		for (int i = lineUsed; i < linePool.size(); i++)
		{
			linePool.get(i).setHidden(true);
		}
	}

	private static boolean poolAttached(Widget container, List<Widget> pool)
	{
		if (pool.isEmpty())
		{
			return true;
		}
		final Widget probe = pool.get(0);
		final Widget[] children = container.getDynamicChildren();
		if (children != null)
		{
			for (Widget w : children)
			{
				if (w == probe)
				{
					return true;
				}
			}
		}
		return false;
	}

	private static Widget create(Widget container, List<Widget> pool, int type)
	{
		final Widget w = container.createChild(type);
		pool.add(w);
		return w;
	}

	private void drawHeader(Widget container, int y, String text)
	{
		final Widget h = textUsed < textPool.size()
			? textPool.get(textUsed)
			: create(container, textPool, WidgetType.TEXT);
		textUsed++;
		h.setText(text);
		h.setTextColor(HEADER_COLOR);
		h.setFontId(FontID.BOLD_12);
		h.setTextShadowed(true);
		h.setOriginalX(START_X);
		h.setOriginalY(y);
		h.setOriginalWidth(ROW_WIDTH);
		h.setOriginalHeight(HEADER_HEIGHT);
		h.setXTextAlignment(WidgetTextAlignment.LEFT);
		h.setYTextAlignment(WidgetTextAlignment.CENTER);
		h.setHidden(false);
		h.revalidate();
	}

	private void drawLine(Widget container, int y)
	{
		final Widget ln = lineUsed < linePool.size()
			? linePool.get(lineUsed)
			: create(container, linePool, WidgetType.RECTANGLE);
		lineUsed++;
		ln.setOriginalX(START_X);
		ln.setOriginalY(y);
		ln.setOriginalWidth(ROW_WIDTH);
		ln.setOriginalHeight(1);
		ln.setFilled(true);
		ln.setTextColor(LINE_COLOR);
		ln.setOpacity(0);
		ln.setHidden(false);
		ln.revalidate();
	}

	@Provides
	BankSorterConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BankSorterConfig.class);
	}
